import logging
from flask import jsonify, request
from src.models import User, UserNotFoundError, ValidationError
from src.database import DatabaseError

logger = logging.getLogger(__name__)

def get_user(user_id):
    try:
        user = User.query.get(user_id)
        if not user:
            raise UserNotFoundError(f"User {user_id} not found")
        return jsonify(user.to_dict())
    except UserNotFoundError as e:
        logger.warning(f"User lookup failed: {user_id}")
        return jsonify({"error": "User not found"}), 404
    except DatabaseError as e:
        logger.error(f"Database error during user lookup: {e}")
        return jsonify({"error": "Internal server error"}), 500

def create_user():
    try:
        data = request.get_json()
        if not data or 'name' not in data:
            raise ValidationError("Missing required field: name")
        user = User.create(data)
        logger.info(f"Created user {user.id}")
        return jsonify(user.to_dict()), 201
    except ValidationError as e:
        logger.warning(f"Validation failed: {e}")
        return jsonify({"error": str(e)}), 400
    except DatabaseError as e:
        logger.error(f"Database error during user create: {e}")
        return jsonify({"error": "Internal server error"}), 500

def update_user(user_id):
    try:
        data = request.get_json()
        user = User.query.get(user_id)
        if not user:
            raise UserNotFoundError(f"User {user_id} not found")
        user.update(data)
        logger.info(f"Updated user {user_id}")
        return jsonify(user.to_dict())
    except UserNotFoundError as e:
        logger.warning(f"Update failed: user {user_id} not found")
        return jsonify({"error": "User not found"}), 404
    except ValidationError as e:
        logger.warning(f"Validation failed during update: {e}")
        return jsonify({"error": str(e)}), 400
    except DatabaseError as e:
        logger.error(f"Database error during update: {e}")
        return jsonify({"error": "Internal server error"}), 500

